import copy,json,secrets
from cryptography.hazmat.primitives.ciphers.aead import AESGCM

def aad(key_id,version):
    return json.dumps([key_id,version],separators=(',',':')).encode()

def rotate_material(store,key_id,new_material):
    if key_id not in store:raise ValueError('unknown logical key')
    if not isinstance(new_material,bytes) or len(new_material)!=32:raise ValueError('fresh 256-bit teaching material required')
    if new_material in store[key_id]['materials'].values():raise ValueError('material must actually change')
    result=copy.deepcopy(store);key=result[key_id];version=max(key['materials'])+1
    key['materials'][version]=new_material;key['current']=version
    return result

def encrypt(store,key_id,plaintext):
    if key_id not in store:raise ValueError('unknown logical key')
    key=store[key_id];version=key['current'];nonce=secrets.token_bytes(12)
    ciphertext=AESGCM(key['materials'][version]).encrypt(nonce,plaintext,aad(key_id,version))
    return {'key_id':key_id,'material_version':version,'nonce':nonce.hex(),'ciphertext':ciphertext.hex()}

def decrypt(store,envelope):
    key_id=envelope['key_id'];version=envelope['material_version']
    if key_id not in store or version not in store[key_id]['materials']:raise ValueError('required historical logical key/material unavailable')
    material=store[key_id]['materials'][version]
    return AESGCM(material).decrypt(bytes.fromhex(envelope['nonce']),bytes.fromhex(envelope['ciphertext']),aad(key_id,version))
